package com.onetickflick;

import net.runelite.client.config.*;

import java.awt.*;

@ConfigGroup("onetickflick")
public interface OneTickFlickConfig extends Config
{
	@ConfigItem(
			keyName = "showOverheadPrayerBar",
			name = "Show overhead prayer bar",
			position = 0,
			description = "Whether to show the prayer bar above your character's head, similar to the RuneLite \"Prayer\" plugin prayer bar")
	default boolean showOverheadPrayerBar()
	{
		return false;
	}

	@ConfigItem(
			keyName = "showOverlayPrayerBar",
			name = "Show overlay prayer bar",
			position = 1,
			description = "Whether to show the overlay prayer bar")
	default boolean showOverlayPrayerBar()
	{
		return true;
	}

	@ConfigItem(
			keyName = "showCombo",
			name = "Show combo counter",
			position = 2,
			description = "Whether to show the combo counter in the overlay. Combo counter is the number of consecutive double clicks within the target zone.")
	default boolean showCombo()
	{
		return true;
	}

	@ConfigItem(
			keyName = "detectPrayerBookClicks",
			name = "Detect prayer book clicks",
			position = 3,
			description = "Whether the overlay should also detect clicks on the prayer book.")
	default boolean detectPrayerBookClicks()
	{
		return true;
	}

	@Units(Units.MILLISECONDS)
	@ConfigItem(
			keyName = "clickDelayMilliseconds",
			name = "Click delay - latency",
			position = 4,
			description = "Add a delay to your clicks to account for latency (ping).")
	@Range(min = 0, max = 500)
	default int clickDelayMilliseconds()
	{
		return 0;
	}

	@ConfigSection(
			position = 5,
			name = "Overlay",
			description = "Configure the overlay settings"
	)
	String overlaySection = "overlaySection";

	@Units(Units.MILLISECONDS)
	@ConfigItem(
			keyName = "greenStart",
			name = "Target zone start",
			description = "How long into the tick the target zone starts. Used as a visual aid and to determine the combo counter.",
			section = overlaySection,
			position = 0
	)
	@Range(min = 0, max = 600)
	default int greenStart()
	{
		return 0;
	}

	@Units(Units.MILLISECONDS)
	@ConfigItem(
			keyName = "greenEnd",
			name = "Target zone end",
			description = "How long into the tick the target zone ends. Used as a visual aid and to determine the combo counter.",
			section = overlaySection,
			position = 1
	)
	@Range(min = 0, max = 600)
	default int greenEnd()
	{
		return 500;
	}

	@Units(Units.PIXELS)
	@ConfigItem(
			keyName = "swipeLineWidth",
			name = "Swipe line width",
			section = overlaySection,
			position = 2,
			description = "Width in pixels of the vertical line that swipes left to right each tick"
	)
	@Range(min = 1, max = 25)
	default int swipeLineWidth()
	{
		return 1;
	}

	@ConfigItem(
			keyName = "comboCounterText",
			name = "Combo counter text",
			section = overlaySection,
			position = 3,
			description = "Text displayed for the combo counter. Use {combo} to insert the current combo count.")
	default String comboCounterText()
	{
		return "Combo: {combo}";
	}

	@ConfigSection(
			position = 6,
			name = "Timeout",
			description = "Configure the timeout settings"
	)
	String timeoutSection = "timeoutSection";

	@ConfigItem(
			keyName = "enableTimeout",
			name = "Enable timeout",
			position = 0,
			section = timeoutSection,
			description = "Whether the overhead bar / overlay should automatically hide after a period without clicking the quick prayer orb.")
	default boolean enableTimeout()
	{
		return false;
	}

	@ConfigItem(
			keyName = "timeoutWhilePrayerActive",
			name = "Timeout while prayer active",
			position = 1,
			section = timeoutSection,
			description = "Whether the overhead bar / overlay should timeout even while you are actively praying.")
	default boolean timeoutWhilePrayerActive()
	{
		return false;
	}

	@Units(Units.SECONDS)
	@ConfigItem(
			keyName = "overlayTimeoutSeconds",
			name = "Timeout",
			position = 2,
			section = timeoutSection,
			description = "How long after last clicking the quick prayer orb the overhead bar / overlay should remain visible")
	@Range(min = 1, max = 600)
	default int overlayTimeoutSeconds()
	{
		return 30;
	}

	@ConfigSection(
			position = 7,
			name = "Overhead Prayer Bar Colors",
			description = "Recolor the various elements of the overhead prayer bar"
	)
	String overheadPrayerBarColorSection = "overheadPrayerBarColorSection";

	@Alpha
	@ConfigItem(
			keyName = "prayerBarFillColor",
			name = "Bar fill color",
			description = "Color of the prayer points fill in the overhead prayer bar",
			section = overheadPrayerBarColorSection,
			position = 0
	)
	default Color prayerBarFillColor()
	{
		return new Color(0, 149, 151, 255);
	}

	@Alpha
	@ConfigItem(
			keyName = "prayerBarBackgroundColor",
			name = "Bar background color",
			description = "Color of the background in the overhead prayer bar",
			section = overheadPrayerBarColorSection,
			position = 1
	)
	default Color prayerBarBackgroundColor()
	{
		return new Color(0, 0, 0, 255);
	}

	@Alpha
	@ConfigItem(
			keyName = "prayerBarSwipeLineColor",
			name = "Swipe line color",
			description = "Color of the vertical line that swipes left to right each tick on the overhead prayer bar",
			section = overheadPrayerBarColorSection,
			position = 2
	)
	default Color prayerBarSwipeLineColor()
	{
		return new Color(0, 255, 255, 255);
	}

	@Alpha
	@ConfigItem(
			keyName = "prayerBarClickLineColor",
			name = "Click line color",
			description = "Color of the vertical lines on the overhead prayer bar that indicate when you clicked",
			section = overheadPrayerBarColorSection,
			position = 3
	)
	default Color prayerBarClickLineColor()
	{
		return new Color(255, 255, 255, 255);
	}

	@ConfigSection(
			position = 8,
			name = "Overlay Colors",
			description = "Recolor the various elements of the overlay"
	)
	String colorSection = "colorSection";

	@Alpha
	@ConfigItem(
			keyName = "targetZoneColor",
			name = "Target zone color",
			description = "Color of the target zone in the overlay",
			section = colorSection,
			position = 0
	)
	default Color targetZoneColor()
	{
		return new Color(0, 255, 0, 255);
	}

	@Alpha
	@ConfigItem(
			keyName = "backgroundColor",
			name = "Background color",
			description = "Color of the background bar in the overlay",
			section = colorSection,
			position = 1
	)
	default Color backgroundColor()
	{
		return new Color(255, 0, 0, 255);
	}

	@Alpha
	@ConfigItem(
			keyName = "clickColor",
			name = "X click color",
			description = "Color of the Xs in the overlay that indicate when you clicked",
			section = colorSection,
			position = 2
	)
	default Color clickColor()
	{
		return new Color(0, 0, 0, 255);
	}

	@Alpha
	@ConfigItem(
			keyName = "swipeLineColor",
			name = "Swipe line color",
			description = "Color of the vertical line that swipes left to right each tick",
			section = colorSection,
			position = 3
	)
	default Color swipeLineColor()
	{
		return new Color(0, 0, 0, 255);
	}

	@Alpha
	@ConfigItem(
			keyName = "borderColor",
			name = "Border color",
			description = "Color of the border around the overlay",
			section = colorSection,
			position = 4
	)
	default Color borderColor()
	{
		return new Color(0, 0, 0, 255);
	}

	@Alpha
	@ConfigItem(
			keyName = "comboTextColor",
			name = "Combo text color",
			description = "Color of the combo counter text in the overlay",
			section = colorSection,
			position = 5
	)
	default Color comboTextColor()
	{
		return new Color(255, 255, 255, 255);
	}
}

package com.onetickflick;

import javax.inject.Inject;
import java.awt.*;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

import lombok.Setter;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

public class OneTickFlickOverlay extends Overlay
{
	private static final int MIN_BAR_HEIGHT = 5;
	private static final int HIDDEN_COMBO_SPACE = 6;
	private static final int COMBO_TEXT_SPACE = 20;
	private static final int DEFAULT_BAR_HEIGHT = 12;
	private static final int DEFAULT_TEXT_SPACE = 20;
	private static final int X_SIZE = 4;
	private static final int TICK_LENGTH = 600;
	private static final int MIN_WIDTH = 50;
	private static final int DEFAULT_WIDTH = 150;
	private static final Dimension DEFAULT_SIZE = new Dimension(DEFAULT_WIDTH, DEFAULT_BAR_HEIGHT + DEFAULT_TEXT_SPACE);

	private final OneTickFlickPlugin plugin;
	private final List<Integer> clickOffsets = new CopyOnWriteArrayList<>();
	private volatile boolean visible = true;
	private boolean showOverlayPrayerBar = true;

	@Setter
	private int greenStart;
	@Setter
	private int greenEnd;
	private boolean showCombo;
	@Setter
	private Color targetZoneColor;
	@Setter
	private Color backgroundColor;
	@Setter
	private Color clickColor;
	@Setter
	private Color swipeLineColor;
	@Setter
	private Color borderColor;
	@Setter
	private Color comboTextColor;
	@Setter
	private String comboCounterText;
	@Setter
	private int swipeLineWidth;


	@Inject
	OneTickFlickOverlay(OneTickFlickPlugin plugin, OneTickFlickConfig config)
	{
		this.plugin = plugin;
		greenStart = config.greenStart();
		greenEnd = config.greenEnd();
		showCombo = config.showCombo();
		showOverlayPrayerBar = config.showOverlayPrayerBar();
		targetZoneColor = config.targetZoneColor();
		backgroundColor = config.backgroundColor();
		clickColor = config.clickColor();
		swipeLineColor = config.swipeLineColor();
		borderColor = config.borderColor();
		comboTextColor = config.comboTextColor();
		comboCounterText = config.comboCounterText();
		swipeLineWidth = config.swipeLineWidth();

		setPosition(OverlayPosition.BOTTOM_LEFT);
		setPreferredSize(DEFAULT_SIZE);
		setMinimumSize(getMinimumHeight());
		setResizable(true);
	}

	void recordClick(int offset)
	{
		clickOffsets.add(offset);
	}

	void newTick()
	{
		clickOffsets.clear();
	}

	void setVisible(boolean v)
	{
		visible = v;
	}

	boolean isVisible()
	{
		return visible;
	}

	public void setShowCombo(boolean showCombo)
	{
		this.showCombo = showCombo;
		setMinimumSize(getMinimumHeight());
	}

	void setShowOverlayPrayerBar(boolean showOverlayPrayerBar)
	{
		this.showOverlayPrayerBar = showOverlayPrayerBar;
		setMinimumSize(getMinimumHeight());
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!visible || (!showOverlayPrayerBar && !showCombo))
		{
			return null;
		}

		Rectangle bounds = getBounds();
		Dimension size = getPreferredSize() == null ? DEFAULT_SIZE : getPreferredSize();

		int width = size.width;
		int height = size.height;
		if (bounds != null && bounds.width > 0 && bounds.height > 0)
		{
			width = Math.max(bounds.width, MIN_WIDTH);
			height = Math.max(bounds.height, getMinimumHeight());
		}

		int barHeight = 0;
		int barY = 0;

		if (showOverlayPrayerBar)
		{
			int reservedSpace = getReservedSpace();
			barHeight = Math.max(MIN_BAR_HEIGHT, height - reservedSpace);
			barY = showCombo ? 0 : (height - barHeight) / 2;

			int greenX1 = width * greenStart / TICK_LENGTH;
			int greenX2 = width * greenEnd / TICK_LENGTH;

			g.setColor(backgroundColor);
			g.fillRect(0, barY, greenX1, barHeight);
			g.fillRect(greenX2, barY, width - greenX2, barHeight);

			g.setColor(targetZoneColor);
			g.fillRect(greenX1, barY, greenX2 - greenX1, barHeight);

			long ms = plugin.millisSinceTick();
			int swipeLineX = (int) (width * ms / (double) TICK_LENGTH);
			swipeLineX = Math.min(swipeLineX, width - swipeLineWidth);

			g.setColor(swipeLineColor);
			g.fillRect(swipeLineX, barY, swipeLineWidth, barHeight);

			g.setColor(borderColor);
			g.drawRect(0, barY, width, barHeight);

			g.setColor(clickColor);
			int xSize = Math.min(X_SIZE, Math.max(1, (barHeight - 1) / 2));
			int y1 = barY + barHeight / 2 - xSize;
			int y2 = barY + barHeight / 2 + xSize;
			for (int offset : clickOffsets)
			{
				int x = width * offset / TICK_LENGTH;
				g.drawLine(x - xSize, y1, x + xSize, y2);
				g.drawLine(x - xSize, y2, x + xSize, y1);
			}
		}

		if (showCombo)
		{
			g.setColor(comboTextColor);
			String text = comboCounterText.replace("{combo}", String.valueOf(plugin.getCombo()));
			int tx = (width - g.getFontMetrics().stringWidth(text)) / 2;
			int ty;
			if (showOverlayPrayerBar)
			{
				ty = barY + barHeight + g.getFontMetrics().getAscent() + 2;
			}
			else
			{
				ty = (height + g.getFontMetrics().getAscent()) / 2;
			}
			g.drawString(text, tx, ty);
		}

		return new Dimension(width, height);
	}

	private int getMinimumHeight()
	{
		if (showOverlayPrayerBar)
		{
			return MIN_BAR_HEIGHT + getReservedSpace();
		}
		if (showCombo)
		{
			return COMBO_TEXT_SPACE;
		}
		return 0;
	}

	private int getReservedSpace()
	{
		if (!showOverlayPrayerBar)
		{
			return 0;
		}
		return showCombo ? COMBO_TEXT_SPACE : HIDDEN_COMBO_SPACE;
	}
}

package com.onetickflick;

import com.google.inject.Provides;

import javax.inject.Inject;

import lombok.AccessLevel;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

@PluginDescriptor(
		name = "1 Tick Flick",
		description = "Visual tick bar and combo counter for 1-tick prayer flicking with the quick prayer orb",
		tags = {"1", "one", "tick", "flick", "prayer", "metronome", "visual", "quick", "orb"}
)
public class OneTickFlickPlugin extends Plugin
{
	private static final int TICK_LENGTH = 600;

	@Inject
	private OverlayManager overlayManager;
	@Inject
	private OneTickFlickOverlay overlay;
	@Inject
	private PrayerBarOverlay prayerBarOverlay;
	@Inject
	private OneTickFlickConfig config;
	@Inject
	private Client client;

	private long lastTickTime;
	private long lastInteraction;
	private final List<Integer> currentTickClicks = new CopyOnWriteArrayList<>(); // A list of times the quick prayer orb was clicked, in milliseconds since the last onGameTick.
	private final List<Integer> nextTickClicks = new CopyOnWriteArrayList<>(); // Only used if the click delay config option causes the click to fall into the next tick.

	@Getter(AccessLevel.PACKAGE)
	private int combo;

	@Override
	protected void startUp()
	{
		lastTickTime = System.currentTimeMillis();
		lastInteraction = lastTickTime;
		combo = 0;

		overlay.setVisible(true);
		prayerBarOverlay.setVisible(true);
		overlay.setShowOverlayPrayerBar(config.showOverlayPrayerBar());
		overlayManager.add(overlay);
		overlayManager.add(prayerBarOverlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(prayerBarOverlay);
		currentTickClicks.clear();
		nextTickClicks.clear();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!event.getGroup().equals("onetickflick"))
		{
			return;
		}

		switch (event.getKey())
		{
			case "showOverlayPrayerBar":
				overlay.setShowOverlayPrayerBar(config.showOverlayPrayerBar());
				break;
			case "greenStart":
				overlay.setGreenStart(config.greenStart());
				break;
			case "greenEnd":
				overlay.setGreenEnd(config.greenEnd());
				break;
			case "showCombo":
				overlay.setShowCombo(config.showCombo());
				break;
			case "comboCounterText":
				overlay.setComboCounterText(config.comboCounterText());
				break;
			case "targetZoneColor":
				overlay.setTargetZoneColor(config.targetZoneColor());
				break;
			case "backgroundColor":
				overlay.setBackgroundColor(config.backgroundColor());
				break;
			case "clickColor":
				overlay.setClickColor(config.clickColor());
				break;
			case "swipeLineColor":
				overlay.setSwipeLineColor(config.swipeLineColor());
				break;
			case "borderColor":
				overlay.setBorderColor(config.borderColor());
				break;
			case "comboTextColor":
				overlay.setComboTextColor(config.comboTextColor());
				break;
			case "swipeLineWidth":
				overlay.setSwipeLineWidth(config.swipeLineWidth());
				break;
			case "prayerBarFillColor":
				prayerBarOverlay.setBarFillColor(config.prayerBarFillColor());
				break;
			case "prayerBarBackgroundColor":
				prayerBarOverlay.setBarBackgroundColor(config.prayerBarBackgroundColor());
				break;
			case "prayerBarSwipeLineColor":
				prayerBarOverlay.setSwipeLineColor(config.prayerBarSwipeLineColor());
				break;
			case "prayerBarClickLineColor":
				prayerBarOverlay.setClickLineColor(config.prayerBarClickLineColor());
				break;
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (currentTickClicks.size() == 2 && currentTickClicks.stream().allMatch(this::inGreenZone))
		{
			combo++;
		}
		else
		{
			combo = 0;
		}

		currentTickClicks.clear();
		overlay.newTick();
		prayerBarOverlay.newTick();
		prayerBarOverlay.onTick();
		lastTickTime = System.currentTimeMillis();

		if (!nextTickClicks.isEmpty())
		{
			for (Integer offset : nextTickClicks)
			{
				currentTickClicks.add(offset);
				overlay.recordClick(offset);
				prayerBarOverlay.recordClick(offset);
			}
			nextTickClicks.clear();
		}

		applyTimeoutVisibility();
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked e)
	{
		Widget widget = e.getWidget();

		if (widget == null
				|| (widget.getId() != InterfaceID.Orbs.PRAYERBUTTON
				&& widget.getId() != InterfaceID.OrbsNomap.PRAYERBUTTON
				&& !(config.detectPrayerBookClicks() && isPrayerBookWidget(widget.getId()))))
		{
			return;
		}

		if (e.getMenuAction() != MenuAction.CC_OP && e.getMenuAction() != MenuAction.CC_OP_LOW_PRIORITY)
		{
			return;
		}

		int offset = (int) (System.currentTimeMillis() - lastTickTime);
		offset += config.clickDelayMilliseconds();

		if (offset >= TICK_LENGTH)
		{
			// If the click is past the current tick, we add it for the next tick instead. It will be added to the overlay on the next onGameTick.
			nextTickClicks.add(offset - TICK_LENGTH);
		}
		else
		{
			currentTickClicks.add(offset);
			overlay.recordClick(offset);
			prayerBarOverlay.recordClick(offset);
		}

		lastInteraction = System.currentTimeMillis();
		if (!overlay.isVisible() || !prayerBarOverlay.isVisible())
		{
			overlay.setVisible(true);
			prayerBarOverlay.setVisible(true);
		}
	}

	private void applyTimeoutVisibility()
	{
		if (config.enableTimeout())
		{
			if (!overlay.isVisible() && !prayerBarOverlay.isVisible())
			{
				return;
			}

			long elapsed = System.currentTimeMillis() - lastInteraction;
			boolean timedOut = elapsed > config.overlayTimeoutSeconds() * 1000L;
			boolean prayerActive = client.getServerVarbitValue(VarbitID.PRAYER_ALLACTIVE) != 0;

			if (timedOut && (config.timeoutWhilePrayerActive() || !prayerActive))
			{
				overlay.setVisible(false);
				prayerBarOverlay.setVisible(false);
			}
		}
		else
		{
			if (!overlay.isVisible())
			{
				overlay.setVisible(true);
			}
			if (!prayerBarOverlay.isVisible())
			{
				prayerBarOverlay.setVisible(true);
			}
		}
	}

	/**
	 * Returns the number of milliseconds since the last tick.
	 */
	long millisSinceTick()
	{
		return System.currentTimeMillis() - lastTickTime;
	}

	/**
	 * Checks if the given milliseconds are within the green zone defined by the config.
	 *
	 * @param ms
	 * @return
	 */
	private boolean inGreenZone(int ms)
	{
		return ms >= config.greenStart() && ms <= config.greenEnd();
	}

	@Provides
	OneTickFlickConfig provideConfig(ConfigManager cm)
	{
		return cm.getConfig(OneTickFlickConfig.class);
	}

	/**
	 * Checks if the given widget ID is a prayer book widget.
	 *
	 * @param widgetId
	 * @return
	 */
	private static boolean isPrayerBookWidget(int widgetId)
	{
		return widgetId >= InterfaceID.Prayerbook.PRAYER1 && widgetId <= InterfaceID.Prayerbook.PRAYER30;
	}
}

package com.onetickflick;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.Skill;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import lombok.Setter;

public class PrayerBarOverlay extends Overlay
{
	private static final int TICK_LENGTH = 600;
	private static final Dimension PRAYER_BAR_SIZE = new Dimension(30, 5);

	private final Client client;
	private final OneTickFlickConfig config;
	private final OneTickFlickPlugin plugin;

	private boolean showingPrayerBar;
	private volatile boolean visible = true;
	private final List<Integer> clickOffsets = new CopyOnWriteArrayList<>();

	@Setter
	private Color barFillColor;
	@Setter
	private Color barBackgroundColor;
	@Setter
	private Color swipeLineColor;
	@Setter
	private Color clickLineColor;

	@Inject
	PrayerBarOverlay(final Client client, final OneTickFlickConfig config, final OneTickFlickPlugin plugin)
	{
		this.client = client;
		this.config = config;
		this.plugin = plugin;
		barFillColor = config.prayerBarFillColor();
		barBackgroundColor = config.prayerBarBackgroundColor();
		swipeLineColor = config.prayerBarSwipeLineColor();
		clickLineColor = config.prayerBarClickLineColor();

		setPosition(OverlayPosition.DYNAMIC);
		setPriority(PRIORITY_HIGH);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverheadPrayerBar() || !showingPrayerBar || !visible)
		{
			return null;
		}

		final int height = client.getLocalPlayer().getLogicalHeight() + 10;
		final LocalPoint localLocation = client.getLocalPlayer().getLocalLocation();
		final Point canvasPoint = Perspective.localToCanvas(client, localLocation, client.getPlane(), height);

		if (canvasPoint == null)
		{
			return null;
		}

		final float ratio = (float) client.getBoostedSkillLevel(Skill.PRAYER) / client.getRealSkillLevel(Skill.PRAYER);

		final int barX = canvasPoint.getX() - 15;
		final int barY = canvasPoint.getY();
		final int barWidth = PRAYER_BAR_SIZE.width;
		final int barHeight = PRAYER_BAR_SIZE.height;

		final int progressFill = (int) Math.ceil(Math.min((barWidth * ratio), barWidth));

		graphics.setColor(barBackgroundColor);
		graphics.fillRect(barX, barY, barWidth, barHeight);
		graphics.setColor(barFillColor);
		graphics.fillRect(barX, barY, progressFill, barHeight);

		long ms = plugin.millisSinceTick();
		int xOffset = (int) (barWidth * ms / (double) TICK_LENGTH);
		xOffset = Math.min(xOffset, barWidth - 1);

		graphics.setColor(swipeLineColor);
		graphics.fillRect(barX + xOffset, barY, 1, barHeight);

		graphics.setColor(clickLineColor);
		for (int offset : clickOffsets)
		{
			int x = barX + barWidth * offset / TICK_LENGTH;
			graphics.fillRect(x, barY, 1, barHeight);
		}

		return null;
	}

	void recordClick(int offset)
	{
		clickOffsets.add(offset);
	}

	void newTick()
	{
		clickOffsets.clear();
	}

	void setVisible(boolean visible)
	{
		this.visible = visible;
	}

	boolean isVisible()
	{
		return visible;
	}

	void onTick()
	{
		final Player localPlayer = client.getLocalPlayer();
		showingPrayerBar = localPlayer != null;
	}
}

